  const [heroVersion] = useState(tournament?.heroVersion ?? 1);
  const [heroBusy, setHeroBusy] = useState(false);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<TournamentSettings>(() => tournament ? { ...DEFAULT_TOURNAMENT_SETTINGS, ...tournament.settings, spectators: true } : tournamentDefaults());
  const [error, setError] = useState("");
